-- Lab SQL Joins

USE sakila;

-- 1. Number of films per category
SELECT category.name, COUNT(film_category.film_id)
FROM film_category
JOIN category ON film_category.category_id = category.category_id
GROUP BY category.name;

-- 2. Store ID, city and country for each store
SELECT s.store_id, ci.city, co.country
FROM store s
JOIN address a ON s.store_id = a.address_id
JOIN city ci ON a.city_id = ci.city_id
JOIN country co ON ci.country_id = co.country_id;

-- 3. Total revenue generated by each store (in dollars)
SELECT s.store_id, SUM(p.amount) AS total_revenue
FROM payment p
JOIN staff s ON p.staff_id = s.staff_id
GROUP BY s.store_id;

-- 4. Average running time of films for each category
SELECT c.name, AVG(f.length) AS average_length
FROM film f
JOIN film_category fc ON f.film_id = fc.film_id
JOIN category c ON fc.category_id = c.category_id
GROUP BY c.name;
